package site.hsu.hub.club.adapter.out.persistence; import jakarta.persistence.*;import site.hsu.hub.club.domain.ClubRole;
@Entity @Table(name="club_users",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","club_id"}))public class ClubUserEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="user_id",nullable=false)private Long userId;@Column(name="club_id",nullable=false)private Long clubId;@Enumerated(EnumType.STRING)@Column(name="club_role",nullable=false)private ClubRole role;protected ClubUserEntity(){}public ClubUserEntity(Long userId,Long clubId,ClubRole role){this.userId=userId;this.clubId=clubId;this.role=role;}public Long clubId(){return clubId;}public ClubRole role(){return role;}}
